BEGIN;

-- Ficha de Bocatabú.
--
-- El relleno no nombraba un solo hecho, canción, álbum o integrante real. formation_year=2008
-- (coincide con MusicBrainz). occupations ampliado con "musician". Premios Casandra 2009,
-- Mejor Grupo de Rock, GANADOR, registrado con dos fuentes independientes.

UPDATE artists SET formation_year = 2008, occupations = '["musician"]'::jsonb
       WHERE slug = 'bocatabu';

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
  SELECT a.id, 'ead83dcf-9e2c-4f69-a557-dad604716a5e', 'e969ab98-7a8c-44f7-925d-c1f19c65903c', 2009, 'Historias Vírgenes', true,
    'Wikipedia (es), «Bocatabú»; robertocavada.com/RC Noticias (Ana Valdez, entrevista con Giorgio Siladi, mayo 2026)'
  FROM artists a WHERE a.slug = 'bocatabu';

INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bocatabú is a Dominican rock band formed in Santo Domingo in early 2008 by singer Giorgio Siladi and guitarist Eduardo Fernández, together with Óscar Paxtot, Francisco Caamaño, Miguel Abreu and Claudia Ponjuán, that became one of the most visible acts in the country’s alternative rock scene of the late 2000s and early 2010s."}]},{"type":"paragraph","content":[{"type":"text","text":"«Historias Vírgenes» and the Casandra","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The band’s debut album, «Historias Vírgenes» (2009), placed the song «Bang Bang» among the most popular Spanish-language rock singles of its moment in the Dominican Republic and led Bocatabú to share stages with international acts including Shakira, Alejandro Sanz, Fito Páez, «Maná» and «Miranda!». The album won the Premios Casandra for Mejor Grupo de Rock in 2009 and received a further nomination in 2010. Dominican press at the time, and Siladi himself years later, described «Historias Vírgenes» as the best-selling physical album in the country’s history; an English-language comparative table of best-selling albums by country lists it instead with a specifically documented figure of about 8,000 copies sold, well below several other Dominican albums in the same list."}]},{"type":"paragraph","content":[{"type":"text","text":"The record deal","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Riding that momentum, Bocatabú signed with a United States record label, toured internationally and performed at Citi Field in New York, where members of the band met Drake and Lil Wayne. A second album, «Vidas Extraviadas», followed in 2012. Looking back on the period years later, Siladi said the contract had cost the band more than it had gained: «Bocatabú firmó su condena el día que firmó un contrato disquero» (“Bocatabú signed its sentence the day it signed a record deal”), he said in 2026, describing a music industry that prioritized sales figures over the group’s artistic direction."}]},{"type":"paragraph","content":[{"type":"text","text":"«Estado Natural» and Mexico City","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In early 2016 the band relocated to Mexico City to continue its career, and on 19 May 2017 released the single «Estado Natural», recorded at «Panoram Studio» — also used by Björk, Spoon, «Zoé» and Ryan Adams — which marked a turn toward 1980s- and 1990s-influenced textures layered over the band’s established sound. A further release, «Canciones Inéditas», followed in 2018, after which the group largely stepped out of public view."}]},{"type":"paragraph","content":[{"type":"text","text":"Legacy","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In May 2026, Siladi broke that silence in a video that named the band’s historic lineup — himself, Eduardo Fernández, Francisco Caamaño, Claudia Ponjuán, Miguel Abreu and Óscar Paxtot — recounted the group’s rise and the impact the United States contract had had on it, and said he wanted to reunite with his former bandmates “to close that cycle in a positive way.” Within days, Dominican outlets including Listín Diario and El Nuevo Diario reported that the band had announced its return to the stage, citing the reaction of fans to Siladi’s video as the reason — the first public sign of activity from a group that had been inactive since 2018."}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'bocatabu'
ON CONFLICT (document_type, owner_artist_id, locale) WHERE document_type = 'artist_biography' DO UPDATE
   SET document = excluded.document, status = 'published', revision = editorial_documents.revision + 1, updated_at = now();
DELETE FROM editorial_entity_references WHERE editorial_document_id IN
  (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
    WHERE a.slug = 'bocatabu' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Bocatabú is a Dominican rock band formed in Santo Domingo in early 2008 by singer Giorgio Siladi and guitarist Eduardo Fernández, together with Óscar Paxtot, Francisco Caamaño, Miguel Abreu and Claudia Ponjuán, that became one of the most visible acts in the country’s alternative rock scene of the late 2000s and early 2010s.

**«Historias Vírgenes» and the Casandra**

The band’s debut album, «Historias Vírgenes» (2009), placed the song «Bang Bang» among the most popular Spanish-language rock singles of its moment in the Dominican Republic and led Bocatabú to share stages with international acts including Shakira, Alejandro Sanz, Fito Páez, «Maná» and «Miranda!». The album won the Premios Casandra for Mejor Grupo de Rock in 2009 and received a further nomination in 2010. Dominican press at the time, and Siladi himself years later, described «Historias Vírgenes» as the best-selling physical album in the country’s history; an English-language comparative table of best-selling albums by country lists it instead with a specifically documented figure of about 8,000 copies sold, well below several other Dominican albums in the same list.

**The record deal**

Riding that momentum, Bocatabú signed with a United States record label, toured internationally and performed at Citi Field in New York, where members of the band met Drake and Lil Wayne. A second album, «Vidas Extraviadas», followed in 2012. Looking back on the period years later, Siladi said the contract had cost the band more than it had gained: «Bocatabú firmó su condena el día que firmó un contrato disquero» (“Bocatabú signed its sentence the day it signed a record deal”), he said in 2026, describing a music industry that prioritized sales figures over the group’s artistic direction.

**«Estado Natural» and Mexico City**

In early 2016 the band relocated to Mexico City to continue its career, and on 19 May 2017 released the single «Estado Natural», recorded at «Panoram Studio» — also used by Björk, Spoon, «Zoé» and Ryan Adams — which marked a turn toward 1980s- and 1990s-influenced textures layered over the band’s established sound. A further release, «Canciones Inéditas», followed in 2018, after which the group largely stepped out of public view.

**Legacy**

In May 2026, Siladi broke that silence in a video that named the band’s historic lineup — himself, Eduardo Fernández, Francisco Caamaño, Claudia Ponjuán, Miguel Abreu and Óscar Paxtot — recounted the group’s rise and the impact the United States contract had had on it, and said he wanted to reunite with his former bandmates “to close that cycle in a positive way.” Within days, Dominican outlets including Listín Diario and El Nuevo Diario reported that the band had announced its return to the stage, citing the reaction of fans to Siladi’s video as the reason — the first public sign of activity from a group that had been inactive since 2018.' WHERE slug = 'bocatabu';

INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bocatabú es una banda de rock dominicana formada en Santo Domingo a inicios de 2008 por el cantante Giorgio Siladi y el guitarrista Eduardo Fernández, junto a Óscar Paxtot, Francisco Caamaño, Miguel Abreu y Claudia Ponjuán, que se convirtió en una de las agrupaciones más visibles de la escena de rock alternativo dominicana de finales de los años 2000 e inicios de los 2010."}]},{"type":"paragraph","content":[{"type":"text","text":"«Historias Vírgenes» y el Casandra","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"El álbum debut de la banda, «Historias Vírgenes» (2009), colocó la canción «Bang Bang» entre los sencillos de rock en español más populares de su momento en República Dominicana y llevó a Bocatabú a compartir escenario con artistas internacionales como Shakira, Alejandro Sanz, Fito Páez, «Maná» y «Miranda!». El álbum ganó el Premio Casandra a Mejor Grupo de Rock en 2009 y recibió una nueva nominación en 2010. La prensa dominicana de la época, y el propio Siladi años después, describieron «Historias Vírgenes» como el álbum físico más vendido en la historia del país; una tabla comparativa en inglés de los álbumes más vendidos por país lo registra en cambio con una cifra específica y documentada de unas 8,000 copias vendidas, muy por debajo de varios otros álbumes dominicanos en esa misma lista."}]},{"type":"paragraph","content":[{"type":"text","text":"El contrato disquero","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Impulsado por ese momento, Bocatabú firmó con una disquera estadounidense, realizó giras internacionales y se presentó en el Citi Field de Nueva York, donde miembros de la banda conocieron a Drake y Lil Wayne. En 2012 llegó un segundo álbum, «Vidas Extraviadas». Al mirar atrás años después, Siladi dijo que el contrato le había costado más a la banda de lo que le había dado: «Bocatabú firmó su condena el día que firmó un contrato disquero», declaró en 2026, describiendo una industria musical que priorizaba las cifras de ventas por encima de la dirección artística del grupo."}]},{"type":"paragraph","content":[{"type":"text","text":"«Estado Natural» y Ciudad de México","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A inicios de 2016 la banda se mudó a Ciudad de México para continuar su carrera, y el 19 de mayo de 2017 publicó el sencillo «Estado Natural», grabado en «Panoram Studio» —usado también por Björk, Spoon, «Zoé» y Ryan Adams—, que marcó un giro hacia texturas de influencia ochentera y noventera sobre el sonido ya establecido de la banda. En 2018 llegó otro lanzamiento, «Canciones Inéditas», tras el cual el grupo se retiró en gran medida de la vida pública."}]},{"type":"paragraph","content":[{"type":"text","text":"Legado","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"En mayo de 2026, Siladi rompió ese silencio con un video en el que nombró la alineación histórica de la banda —él mismo, Eduardo Fernández, Francisco Caamaño, Claudia Ponjuán, Miguel Abreu y Óscar Paxtot—, relató el ascenso del grupo y el impacto que había tenido en él el contrato estadounidense, y dijo que quería reencontrarse con sus excompañeros “para cerrar ese ciclo de manera positiva”. Días después, medios dominicanos como Listín Diario y El Nuevo Diario reportaron que la banda había anunciado su regreso a los escenarios, citando la reacción de los fanáticos al video de Siladi como la razón — la primera señal pública de actividad de un grupo inactivo desde 2018."}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'bocatabu'
ON CONFLICT (document_type, owner_artist_id, locale) WHERE document_type = 'artist_biography' DO UPDATE
   SET document = excluded.document, status = 'published', revision = editorial_documents.revision + 1, updated_at = now();
DELETE FROM editorial_entity_references WHERE editorial_document_id IN
  (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
    WHERE a.slug = 'bocatabu' AND d.locale = 'es' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_es = 'Bocatabú es una banda de rock dominicana formada en Santo Domingo a inicios de 2008 por el cantante Giorgio Siladi y el guitarrista Eduardo Fernández, junto a Óscar Paxtot, Francisco Caamaño, Miguel Abreu y Claudia Ponjuán, que se convirtió en una de las agrupaciones más visibles de la escena de rock alternativo dominicana de finales de los años 2000 e inicios de los 2010.

**«Historias Vírgenes» y el Casandra**

El álbum debut de la banda, «Historias Vírgenes» (2009), colocó la canción «Bang Bang» entre los sencillos de rock en español más populares de su momento en República Dominicana y llevó a Bocatabú a compartir escenario con artistas internacionales como Shakira, Alejandro Sanz, Fito Páez, «Maná» y «Miranda!». El álbum ganó el Premio Casandra a Mejor Grupo de Rock en 2009 y recibió una nueva nominación en 2010. La prensa dominicana de la época, y el propio Siladi años después, describieron «Historias Vírgenes» como el álbum físico más vendido en la historia del país; una tabla comparativa en inglés de los álbumes más vendidos por país lo registra en cambio con una cifra específica y documentada de unas 8,000 copias vendidas, muy por debajo de varios otros álbumes dominicanos en esa misma lista.

**El contrato disquero**

Impulsado por ese momento, Bocatabú firmó con una disquera estadounidense, realizó giras internacionales y se presentó en el Citi Field de Nueva York, donde miembros de la banda conocieron a Drake y Lil Wayne. En 2012 llegó un segundo álbum, «Vidas Extraviadas». Al mirar atrás años después, Siladi dijo que el contrato le había costado más a la banda de lo que le había dado: «Bocatabú firmó su condena el día que firmó un contrato disquero», declaró en 2026, describiendo una industria musical que priorizaba las cifras de ventas por encima de la dirección artística del grupo.

**«Estado Natural» y Ciudad de México**

A inicios de 2016 la banda se mudó a Ciudad de México para continuar su carrera, y el 19 de mayo de 2017 publicó el sencillo «Estado Natural», grabado en «Panoram Studio» —usado también por Björk, Spoon, «Zoé» y Ryan Adams—, que marcó un giro hacia texturas de influencia ochentera y noventera sobre el sonido ya establecido de la banda. En 2018 llegó otro lanzamiento, «Canciones Inéditas», tras el cual el grupo se retiró en gran medida de la vida pública.

**Legado**

En mayo de 2026, Siladi rompió ese silencio con un video en el que nombró la alineación histórica de la banda —él mismo, Eduardo Fernández, Francisco Caamaño, Claudia Ponjuán, Miguel Abreu y Óscar Paxtot—, relató el ascenso del grupo y el impacto que había tenido en él el contrato estadounidense, y dijo que quería reencontrarse con sus excompañeros “para cerrar ese ciclo de manera positiva”. Días después, medios dominicanos como Listín Diario y El Nuevo Diario reportaron que la banda había anunciado su regreso a los escenarios, citando la reacción de los fanáticos al video de Siladi como la razón — la primera señal pública de actividad de un grupo inactivo desde 2018.' WHERE slug = 'bocatabu';

COMMIT;
